"""Revision-sheet PDF generated by plain code from validated content (no model call)."""
import re
from pathlib import Path

from fpdf import FPDF

FONT_CANDIDATES = [
    "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
    "/usr/share/fonts/TTF/DejaVuSans.ttf",
    "/usr/share/fonts/dejavu/DejaVuSans.ttf",
    "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
]


_SYMBOLS = {
    r"\\cdot": "·", r"\\times": "×", r"\\div": "÷", r"\\pm": "±", r"\\leq": "≤", r"\\le": "≤", r"\\geq": "≥", r"\\ge": "≥",
    r"\\neq": "≠", r"\\approx": "≈", r"\\infty": "∞", r"\\to": "→", r"\\rightarrow": "→", r"\\Rightarrow": "⇒", r"\\in": "∈",
    r"\\int": "∫", r"\\sum": "Σ", r"\\prod": "Π", r"\\sqrt": "√", r"\\partial": "∂", r"\\alpha": "α", r"\\beta": "β",
    r"\\lambda": "λ", r"\\pi": "π", r"\\theta": "θ", r"\\Delta": "Δ", r"\\delta": "δ", r"\\lim": "lim", r"\\,": " ", r"\\;": " ",
    r"\\left": "", r"\\right": "",
}
_SUP = str.maketrans("0123456789+-nhix()", "⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻ⁿʰⁱˣ⁽⁾")


def latex_to_text(s: str) -> str:
    """Readable plain-text rendering of simple LaTeX for the PDF (the web UI renders it with KaTeX)."""
    if "$" not in s and "\\" not in s:
        return s
    s = re.sub(r"\$\$?(.+?)\$?\$", lambda m: m.group(1), s)
    s = re.sub(r"\\frac\{([^{}]*)\}\{([^{}]*)\}", r"(\1)/(\2)", s)
    s = re.sub(r"\\(?:text|mathrm|mathbf|operatorname)\{([^{}]*)\}", r"\1", s)
    s = re.sub(r"\\(int|sum)_\{?([^{}\s^]+)\}?\^\{?([^{}\s]+?)\}?(?=[\s(\\]|$)", lambda m: ("∫" if m.group(1) == "int" else "Σ") + f"[{m.group(2)}→{m.group(3)}]", s)
    s = re.sub(r"\^\{([^{}]*)\}", lambda m: m.group(1).translate(_SUP) if all(c in "0123456789+-nhix()" for c in m.group(1)) else "^(" + m.group(1) + ")", s)
    s = re.sub(r"\^([0-9a-z])", lambda m: m.group(1).translate(_SUP), s)
    s = re.sub(r"_\{([^{}]*)\}", r"_\1", s)
    for k, v in sorted(_SYMBOLS.items(), key=lambda kv: -len(kv[0])):
        s = re.sub(k + (r"(?![A-Za-z])" if k[-1].isalpha() else ""), v, s)
    s = re.sub(r"([∫Σ])_\{?([^{}\s^]+)\}?\^\{?([^{}\s]+?)\}?(?=[\s(]|$)", r"\1[\2→\3]", s)
    return s.replace("{", "").replace("}", "")


def revision_pdf(course_title: str, revision: dict, demo: bool, refs_to_pages: dict[str, str]) -> bytes:
    pdf = FPDF()
    pdf.set_auto_page_break(True, margin=15)
    pdf.add_page()
    font = next((f for f in FONT_CANDIDATES if Path(f).exists()), None)
    if font:
        pdf.add_font("Body", "", font)
        family = "Body"
        try:
            pdf.set_text_shaping(True)  # Arabic shaping when uharfbuzz is installed
        except Exception:
            pass
    else:
        family = "Helvetica"

    def txt(s: str) -> str:
        s = latex_to_text(s)
        return s if font else s.encode("latin-1", "replace").decode("latin-1")

    def cite(cs):
        return txt(" [" + ", ".join(refs_to_pages.get(c, c) for c in cs) + "]") if cs else ""

    pdf.set_font(family, size=16)
    pdf.multi_cell(0, 9, txt(course_title), new_x="LMARGIN", new_y="NEXT")
    pdf.set_font(family, size=9)
    pdf.multi_cell(0, 5, txt("Fiche de révision LessonForge" + (" — mode démo (contenu non généré par IA)" if demo else "")), new_x="LMARGIN", new_y="NEXT")
    pdf.ln(3)
    for s in revision.get("summaries", []):
        pdf.set_font(family, size=13)
        pdf.multi_cell(0, 7, txt(s["chapter_title"]), new_x="LMARGIN", new_y="NEXT")
        pdf.set_font(family, size=10)
        for b in s["bullets"]:
            pdf.multi_cell(0, 5.5, txt("• " + b), new_x="LMARGIN", new_y="NEXT")
        pdf.set_font(family, size=8)
        pdf.multi_cell(0, 5, cite(s.get("citations", [])), new_x="LMARGIN", new_y="NEXT")
        pdf.ln(2)
    cards = revision.get("flashcards", [])
    if cards:
        pdf.set_font(family, size=13)
        pdf.multi_cell(0, 8, txt("Formules et termes clés"), new_x="LMARGIN", new_y="NEXT")
        pdf.set_font(family, size=10)
        for c in cards:
            pdf.multi_cell(0, 5.5, txt(f"{c['front']} : {c['back']}") + cite(c.get("citations", [])), new_x="LMARGIN", new_y="NEXT")
    return bytes(pdf.output())
